from pathlib import Path
import re
ROOT=Path(__file__).resolve().parents[1]
APP=ROOT/'site'/'app.js'; IDX=ROOT/'site'/'index.html'; CSS=ROOT/'site'/'styles.css'
s=APP.read_text(encoding='utf-8')

# Helpers after programCareerCoverage
anchor="function programCareerCoverage(p,savedOnly=false){const set=savedOnly?state.savedCareers:D.careers.map(c=>c.name);let n=0;set.forEach(name=>{const c=careerByName(name); if(c&&supportStrength(c.support[p.code])>=2)n++});return n}\n"
helper=r'''function evidenceLabel(c){return D.evidenceStatusLabels?.[c.evidenceStatus]||String(c.evidenceStatus||'Evidence available').replaceAll('_',' ')}
function evidenceClass(c){return c.evidenceStatus==='verified_current_market'?'market':c.evidenceStatus?.startsWith('verified')?'verified':'established'}
function roleKindLabel(c){return D.roleKindLabels?.[c.roleKind]||String(c.roleKind||'career').replaceAll('_',' ')}
function currentPostingCount(c){return (c.recentPostings||[]).length}
function observedTitleCount(c){return (c.observedTitles||[]).length}
function postingSalaryText(c){const m=c.observedMarketSalary;if(!m)return null;return `${money(m.observedMin)}–${money(m.observedMax)} (${m.count} posting${m.count===1?'':'s'})`}
function sourceLink(src,label){return src?.url?`<a href="${esc(src.url)}" target="_blank" rel="noopener">${esc(label||src.organization||src.title)} ↗</a>`:esc(label||'Source')}
function uniqueObservedTitles(c){const seen=new Set();return (c.observedTitles||[]).filter(x=>{const k=(x.title||'').toLowerCase();if(!k||seen.has(k))return false;seen.add(k);return true})}
function explicitEdgesFor(name){return (D.careerEdges||[]).filter(e=>e.fromCareer===name)}
'''
if helper not in s:
    s=s.replace(anchor,anchor+'\n'+helper)

# route
s=s.replace("if(r==='progression')return renderProgression();if(r==='programs')", "if(r==='progression')return renderProgression();if(r==='evidence')return renderEvidence();if(r==='programs')")

# home paragraph + stats/market feature
s=s.replace("This is not a career test. Use guided questions, filterable career and college browsers, and real-world follow-up ideas to learn what fits—and what still needs experience.","This is not a career test or a closed list of jobs. Explore a growing, evidence-backed map of animal and wildlife career families, real employer titles, college preparation, and questions worth testing through experience.")
s=s.replace("<button class=\"btn\" onclick=\"go('progression')\">Explore career progression</button><button class=\"btn\" onclick=\"go('programs')\">Browse college paths</button>","<button class=\"btn\" onclick=\"go('progression')\">Explore career progression</button><button class=\"btn\" onclick=\"go('evidence')\">Market & evidence</button><button class=\"btn\" onclick=\"go('programs')\">Browse college paths</button>")
s=s.replace("<div class=\"card feature-card\" onclick=\"go('dashboard')\"><div class=\"iconbox\">↻</div>","<div class=\"card feature-card\" onclick=\"go('evidence')\"><div class=\"iconbox\">✓</div><div class=\"kicker\">Evidence</div><h3>See the real market behind the map</h3><p>Inspect observed job titles, current/recent postings, qualification standards, credentials, sources and what still needs more research.</p></div><div class=\"card feature-card\" onclick=\"go('dashboard')\"><div class=\"iconbox\">↻</div>")

# replace careerCard
start=s.index('function careerCard(c,rec=false)')
end=s.index('\n\nfunction renderCareers()',start)
career_card=r'''function careerCard(c,rec=false){const d=c.details||{}, entry=c.entrySalary?`${money(c.entrySalary[0])}–${money(c.entrySalary[1])}`:'—', mid=c.midSalary?`${money(c.midSalary[0])}–${money(c.midSalary[1])}`:'—',observedPay=postingSalaryText(c);return `<div class="card career-card"><button class="save-btn ${state.savedCareers.includes(c.name)?'saved':''}" title="Save" onclick="event.stopPropagation();toggle(state.savedCareers,'${esc(c.name).replace(/'/g,"\\'")}');renderCareers()">★</button><div class="kicker">${esc(c.domain?.name||c.category)} • ${esc(c.roleFamily?.name||'')}</div><h3 class="card-title">${esc(c.name)}</h3><div class="tagrow"><span class="tag evidence ${evidenceClass(c)}">${esc(evidenceLabel(c))}</span><span class="tag">${esc(roleKindLabel(c))}</span>${currentPostingCount(c)?`<span class="tag green">${currentPostingCount(c)} recent posting${currentPostingCount(c)===1?'':'s'}</span>`:''}</div><p>${esc(c.roleFocus||d['Typical education / progression']||'')}</p><div class="tagrow">${c.workTags.slice(0,5).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}<span class="tag green">${esc(c.directContact)} animal contact</span></div><div class="meta"><div><small>Education</small><b>${esc(c.educationBand)}</b></div><div><small>Market titles observed</small><b>${observedTitleCount(c)||'—'}</b></div><div><small>${observedPay?'Observed posting pay':'Broad mid proxy'}</small><b>${observedPay||mid}</b></div></div>${rec&&c._a?.reasons?.length?`<div class="notice"><b>Why it is showing:</b> ${c._a.reasons.map(esc).join(', ')}</div>`:''}<div class="actions"><button class="btn small primary" onclick="openCareer('${esc(c.name).replace(/'/g,"\\'")}')">Explore role & evidence</button><button class="btn small" onclick="toggleCompareCareer('${esc(c.name).replace(/'/g,"\\'")}')">Compare</button></div></div>`}'''
s=s[:start]+career_card+s[end:]

# replace career explorer blocks through toggleCompareCareer
start=s.index('function renderCareers()')
end=s.index('function toggleCompareCareer',start)
career_explorer=r'''function renderCareers(){app.innerHTML=`<div class="page"><div class="section-title"><div><div class="eyebrow">93 canonical roles • 32 role families</div><h1>Career Explorer</h1><p>These roles organize a much larger market of employer-specific titles and specializations. Browse by domain or role family, then open any role to see observed titles and current/recent evidence.</p></div><div class="actions"><button class="btn soft" id="recToggle">Show what matches me</button><button class="btn" onclick="go('progression')">Career progression →</button><button class="btn" onclick="go('evidence')">How the evidence works</button></div></div><div class="split"><aside class="card filters" id="careerFilters"></aside><section><div class="resultbar"><span id="careerCount"></span><select id="careerSort"><option value="name">Sort: A–Z</option><option value="match">Sort: current match</option><option value="evidence">Sort: market evidence</option><option value="salary">Sort: pay evidence</option></select></div><div class="grid cols-2" id="careerResults"></div></section></div></div><div id="compareCareerDrawer"></div>`;buildCareerFilters();updateCareerResults();document.getElementById('careerSort').onchange=updateCareerResults;document.getElementById('recToggle').onclick=e=>{e.target.classList.toggle('primary');e.target.dataset.on=e.target.dataset.on==='1'?'0':'1';updateCareerResults()}}
function buildCareerFilters(){const cats=[...new Set(D.careers.map(c=>c.category))];const tags=[...new Set(D.careers.flatMap(c=>c.workTags))].sort();const domains=D.domains||[];document.getElementById('careerFilters').innerHTML=`<div class="filter-section"><label class="head">Search all titles & evidence</label><input id="careerSearch" class="searchbox" placeholder="Career, observed title, employer, skill…"></div><div class="filter-section"><label class="head">Saved / linked</label><label class="check"><input type="checkbox" id="savedCareerOnly"> Show saved careers only</label><label class="check"><input type="checkbox" id="savedPathCareerOnly"> Only careers supported by a saved college path</label><div class="help">${state.savedPrograms.length?`${state.savedPrograms.length} saved path${state.savedPrograms.length===1?'':'s'} available for linking.`:'Save one or more college paths to use the second filter.'}</div></div><div class="filter-section"><label class="head">Domain</label><select id="domainFilter"><option value="">All domains</option>${domains.map(d=>`<option value="${d.domain_id}">${esc(d.name)} (${d.roleCount})</option>`).join('')}</select></div><div class="filter-section"><label class="head">Role family</label><select id="familyFilter"><option value="">All role families</option>${D.roleFamilies.map(f=>`<option value="${f.family_id}" data-domain="${f.domain_id}">${esc(f.name)} (${f.role_count})</option>`).join('')}</select></div><div class="filter-section"><label class="head">Market evidence</label><label class="check"><input type="checkbox" id="postingOnly"> Has current/recent posting evidence</label><select id="evidenceFilter"><option value="">Any evidence status</option>${Object.entries(D.evidenceStatusLabels||{}).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></div><div class="filter-section"><label class="head">Role type</label><select id="roleKindFilter"><option value="">Any type</option>${Object.entries(D.roleKindLabels||{}).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></div><div class="filter-section"><label class="head">Direct animal contact</label><select id="contactFilter"><option value="">Any</option><option>High</option><option>Moderate</option><option>Low / variable</option></select></div><div class="filter-section"><label class="head">Education path</label><select id="eduFilter"><option value="">Any</option>${[...new Set(D.careers.map(c=>c.educationBand))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="filter-section"><label class="head">Kinds of work</label>${tags.map(t=>`<label class="check"><input type="checkbox" class="workTag" value="${esc(t)}"> ${esc(t)}</label>`).join('')}</div><div class="filter-section"><label class="head">Supported strongly by one specific college path</label><select id="pathFilter"><option value="">Any path</option>${D.programs.map(p=>`<option value="${p.code}">${p.code} — ${esc(p.title)}</option>`).join('')}</select></div><button class="btn small" id="clearCareer">Clear filters</button>`;['careerSearch','domainFilter','familyFilter','evidenceFilter','roleKindFilter','contactFilter','eduFilter','pathFilter','savedCareerOnly','savedPathCareerOnly','postingOnly'].forEach(id=>document.getElementById(id).addEventListener('input',updateCareerResults));document.querySelectorAll('.workTag').forEach(x=>x.onchange=updateCareerResults);document.getElementById('domainFilter').addEventListener('change',e=>{const fam=document.getElementById('familyFilter');if(fam.value&&fam.selectedOptions[0]?.dataset.domain!==e.target.value)fam.value='';updateCareerResults()});document.getElementById('clearCareer').onclick=()=>{document.querySelectorAll('#careerFilters input').forEach(x=>{if(x.type==='checkbox')x.checked=false;else x.value=''});document.querySelectorAll('#careerFilters select').forEach(x=>x.value='');updateCareerResults()}}
function updateCareerResults(){let arr=D.careers.map(c=>({...c,_a:affinity(c.dims)}));const q=(document.getElementById('careerSearch')?.value||'').toLowerCase(),domain=document.getElementById('domainFilter')?.value||'',family=document.getElementById('familyFilter')?.value||'',evidence=document.getElementById('evidenceFilter')?.value||'',kind=document.getElementById('roleKindFilter')?.value||'',contact=document.getElementById('contactFilter')?.value||'',edu=document.getElementById('eduFilter')?.value||'',path=document.getElementById('pathFilter')?.value||'',work=[...document.querySelectorAll('.workTag:checked')].map(x=>x.value), rec=document.getElementById('recToggle')?.dataset.on==='1',savedOnly=document.getElementById('savedCareerOnly')?.checked||false,linkedOnly=document.getElementById('savedPathCareerOnly')?.checked||false,postingOnly=document.getElementById('postingOnly')?.checked||false;arr=arr.filter(c=>{const market=[...(c.aliases||[]),...(c.observedTitles||[]).map(x=>x.title),...(c.recentPostings||[]).flatMap(x=>[x.title,x.employer,x.location])].join(' ');const blob=(c.name+' '+c.roleFocus+' '+c.roleFamily?.name+' '+Object.values(c.details||{}).join(' ')+' '+c.workTags.join(' ')+' '+market+' '+(c.competencies||[]).map(x=>x.name).join(' ')).toLowerCase();return (!q||blob.includes(q))&&(!domain||c.domain?.id===domain)&&(!family||c.roleFamily?.id===family)&&(!evidence||c.evidenceStatus===evidence)&&(!kind||c.roleKind===kind)&&(!contact||c.directContact===contact)&&(!edu||c.educationBand===edu)&&(!path||['S','SG'].includes(c.support[path]))&&work.every(t=>c.workTags.includes(t))&&(!rec||c._a.score>.47)&&(!savedOnly||state.savedCareers.includes(c.name))&&(!linkedOnly||careerSupportedBySavedPath(c))&&(!postingOnly||currentPostingCount(c)>0)});const sort=document.getElementById('careerSort')?.value||'name';if(sort==='match')arr.sort((a,b)=>b._a.score-a._a.score);else if(sort==='evidence')arr.sort((a,b)=>currentPostingCount(b)-currentPostingCount(a)||observedTitleCount(b)-observedTitleCount(a)||a.name.localeCompare(b.name));else if(sort==='salary')arr.sort((a,b)=>((b.observedMarketSalary?.medianHigh||b.midSalary?.[0]||0)-(a.observedMarketSalary?.medianHigh||a.midSalary?.[0]||0)));else arr.sort((a,b)=>a.name.localeCompare(b.name));document.getElementById('careerCount').textContent=`${arr.length} of ${D.dataSummary.canonicalRoles} canonical roles`;document.getElementById('careerResults').innerHTML=arr.map(c=>careerCard(c,rec||sort==='match')).join('')||`<div class="empty">No roles match these filters.${linkedOnly&&!state.savedPrograms.length?' Save a college path first, or turn off the saved-path restriction.':' Remove one or more filters.'}</div>`;renderCareerCompareDrawer()}
'''
s=s[:start]+career_explorer+s[end:]

# explicit progression helper: replace progressionOptions with wrapper preserving algorithm fallback
old_start=s.index('function progressionOptions(current,eduRank,expRank)')
old_end=s.index('\n\nfunction render(r)',old_start)
progress_helpers=r'''function inferredProgressionOptions(current,eduRank,expRank){const cs=careerStage(current),cm=midPoint(current),maxNaturalDelta=expRank>=2?2:1;const pool=D.careers.filter(c=>c.name!==current.name&&eduRankFromCareer(c)<9).map(c=>({c,sim:careerSimilarity(current,c),stage:careerStage(c),edu:eduRankFromCareer(c),mid:midPoint(c),inferred:true}));const natural=pool.filter(x=>x.sim>=.54&&x.stage>cs&&x.stage-cs<=maxNaturalDelta&&x.edu<=eduRank&&(x.stage<4||expRank>=2)).sort((a,b)=>b.sim-a.sim||b.mid-a.mid).slice(0,7);const naturalNames=new Set(natural.map(x=>x.c.name));const growth=pool.filter(x=>!naturalNames.has(x.c.name)&&x.sim>=.48&&x.stage>cs&&((x.edu>eduRank)||(x.stage-cs>maxNaturalDelta)||(x.stage>=4&&expRank<2)||(x.mid&&cm&&x.mid>cm*1.08))).sort((a,b)=>b.sim-a.sim).slice(0,8);const used=new Set([...naturalNames,...growth.map(x=>x.c.name)]);const lateral=pool.filter(x=>!used.has(x.c.name)&&x.sim>=.50&&Math.abs(x.stage-cs)<=1&&x.edu<=Math.max(eduRank,1)&&(x.c.category!==current.category||tagOverlap(current.workTags,x.c.workTags)>=.45)).sort((a,b)=>b.sim-a.sim).slice(0,8);return {natural,growth,lateral}}
function explicitProgressionOptions(current){const natural=[],growth=[],lateral=[];for(const e of explicitEdgesFor(current.name)){const c=careerByName(e.toCareer);if(!c)continue;const o={c,sim:careerSimilarity(current,c),edge:e,inferred:false};if(e.relationship_type==='lateral'||e.relationship_type==='professional_assignment')lateral.push(o);else if(e.relationship_type==='natural_growth')natural.push(o);else growth.push(o)}return {natural,growth,lateral}}
function progressionOptions(current,eduRank,expRank){const explicit=explicitProgressionOptions(current),inf=inferredProgressionOptions(current,eduRank,expRank);const merge=(a,b,limit)=>{const seen=new Set(a.map(x=>x.c.name));return [...a,...b.filter(x=>!seen.has(x.c.name))].slice(0,limit)};return {natural:merge(explicit.natural,inf.natural,8),growth:merge(explicit.growth,inf.growth,9),lateral:merge(explicit.lateral,inf.lateral,9)}}'''
s=s[:old_start]+progress_helpers+s[old_end:]

# route includes evidence already done, but need function render line perhaps replaced earlier okay
# Replace progressionCard to show explicit evidence
start=s.index('function progressionCard(o,kind,eduRank)')
end=s.index('\nfunction renderProgression()',start)
prog_card=r'''function progressionCard(o,kind,eduRank){const c=o.c,d=c.details||{},mid=c.midSalary?`${money(c.midSalary[0])}–${money(c.midSalary[1])}`:'—',needs=eduRankFromCareer(c)>eduRank,e=o.edge;const why=e?`${e.notes||''}${e.education_change&&e.education_change!=='none'?` Education change: ${e.education_change}.`:''}${e.experience_change?` Experience: ${e.experience_change}.`:''}`:progressionReason(careerByName(state.progression.career),c,eduRank,kind);return `<div class="progression-card"><div class="kicker">${kind==='natural'?'Natural growth':kind==='growth'?'Possible growth':'Lateral option'}</div><h3>${esc(c.name)}</h3><p>${esc(c.roleFocus)}</p><div class="tagrow"><span class="tag ${e?'green':'gold'}">${e?`Explicit ${esc(e.evidence_status)} edge`:'Inferred nearby option'}</span><span class="tag ${needs?'gold':'green'}">${needs?'Additional education likely':'Fits assumed education'}</span></div><div class="meta"><div><small>Education</small><b>${esc(c.educationBand)}</b></div><div><small>Market evidence</small><b>${currentPostingCount(c)} postings</b></div><div><small>Similarity</small><b>${Math.round(o.sim*100)}%</b></div></div><p class="progression-why">${esc(why)}</p>${e?.source?`<div class="source-mini">${sourceLink(e.source,e.source.organization)}</div>`:''}<div class="actions"><button class="btn small primary" onclick="openCareer('${esc(c.name).replace(/'/g,"\\'")}')">Explore career</button><button class="btn small" onclick="state.progression.career='${esc(c.name).replace(/'/g,"\\'")}';save();renderProgression()">Continue from here</button></div></div>`}'''
s=s[:start]+prog_card+s[end:]

# Slight progression intro update
s=s.replace('The results distinguish natural growth, broader growth possibilities, and lateral moves rather than assuming one fixed ladder.','The results distinguish natural growth, broader growth possibilities, and lateral moves. Explicit researched transitions appear first; similarity-based options fill gaps and are clearly labeled as inferred.')
s=s.replace('Use this as an exploration map, not a promotion schedule. Career titles vary by employer; the tool is matching the career data by work content, education, responsibility level, and related skills.','Use this as an exploration map, not a promotion schedule. Green “explicit edge” labels come from curated progression relationships; gold “inferred” labels are similarity-based possibilities that still need stronger market validation.')

# Replace openCareer
start=s.index('function openCareer(name)')
end=s.index('\nfunction careerExcept',start)
open_career=r'''function openCareer(name){const c=careerByName(name),d=c.details||{};const groups=[['Strong/direct paths',['S','SG']],['Credible with planning',['C','C*']],['Graduate-oriented foundations',['G']],['Weakly aligned',['N']]];const quick=['More direct animal contact','More research','More fieldwork','Less graduate school','More conservation','More behavior'];const titles=uniqueObservedTitles(c).slice(0,14),posts=(c.recentPostings||[]).slice(0,8),pay=postingSalaryText(c);modalRoot.innerHTML=`<div class="modal-back" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div><div class="kicker">${esc(c.domain?.name||c.category)} • ${esc(c.roleFamily?.name||'')}</div><h2>${esc(c.name)}</h2></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="tagrow"><span class="tag evidence ${evidenceClass(c)}">${esc(evidenceLabel(c))}</span><span class="tag">${esc(roleKindLabel(c))}</span><span class="tag">Last verified ${esc(c.lastVerified||D.dataSummary.asOf)}</span></div><p style="font-size:18px">${esc(c.roleFocus)}</p><div class="notice"><b>This is a canonical exploration role, not a limit on job titles.</b> Employers may use many different titles for related work. The market examples below show titles actually observed in this research snapshot; their absence does not mean other titles or employers do not exist.</div>${titles.length?`<h3>Observed real-world titles</h3><div class="observed-grid">${titles.map(x=>`<div class="observed-title"><b>${esc(x.title)}</b><span>${esc(x.organization||'')} ${x.location?`• ${esc(x.location)}`:''}</span>${x.source?`<small>${sourceLink(x.source,x.source.organization)}</small>`:''}</div>`).join('')}</div>`:''}${posts.length?`<h3>Current / recent market examples</h3><div class="posting-list">${posts.map(x=>`<div class="posting"><div><b>${esc(x.title)}</b><span>${esc(x.employer)}${x.location?` • ${esc(x.location)}`:''}${x.posted_date?` • ${esc(x.posted_date)}`:''}</span></div><div class="posting-right">${x.salary_min!=null?`<b>${x.salary_unit==='hourly'?'$'+x.salary_min.toFixed(2)+'/hr':money(x.salary_min)+'–'+money(x.salary_max||x.salary_min)}</b>`:''}<a href="${esc(x.url)}" target="_blank" rel="noopener">posting ↗</a></div></div>`).join('')}</div>`:''}<div class="detail-grid evidence-summary"><div class="detail"><h4>Education / progression</h4><p>${esc(c.educationBand)}</p></div><div class="detail"><h4>Market evidence</h4><p>${observedTitleCount(c)} observed title${observedTitleCount(c)===1?'':'s'}; ${currentPostingCount(c)} current/recent posting${currentPostingCount(c)===1?'':'s'}.</p></div><div class="detail"><h4>Observed posting pay</h4><p>${pay||'Not enough posting-level salary observations yet.'}</p></div><div class="detail"><h4>Broad occupation proxy</h4><p>${c.midSalary?`Mid proxy ${money(c.midSalary[0])}–${money(c.midSalary[1])}.`:esc(d['Salary context']||'No dedicated O*NET/BLS occupation; use market and related-science evidence.')}</p></div></div>${c.competencies?.length?`<h3>Competencies that matter</h3><div class="chipbar">${c.competencies.map(x=>`<span class="chip static" title="${esc(x.description)}">${esc(x.name)}</span>`).join('')}</div>`:''}${c.qualificationProfiles?.length?`<h3>Formal qualification rules</h3>${c.qualificationProfiles.map(q=>`<div class="detail qualification"><h4>${esc(q.organization)}${q.series_code?` — ${esc(q.series_code)}`:''}</h4><p>${esc(q.education_requirement||'')} ${esc(q.coursework_requirement||'')} ${esc(q.experience_requirement||'')}</p><small><a href="${esc(q.source_url)}" target="_blank" rel="noopener">official requirement ↗</a></small></div>`).join('')}`:''}${c.credentials?.length?`<h3>Credentials / permits</h3>${c.credentials.map(x=>`<div class="detail qualification"><h4>${esc(x.name)} <span class="tag">${esc(x.relationship)}</span></h4><p>${esc(x.description||x.notes||'')}</p>${x.source_url?`<small><a href="${esc(x.source_url)}" target="_blank" rel="noopener">credential source ↗</a></small>`:''}</div>`).join('')}`:''}${c.evidence?.length?`<h3>Explicit evidence claims</h3>${c.evidence.map(x=>`<div class="evidence-claim"><b>${esc(x.claim_type.replaceAll('_',' '))}</b><span>${esc(x.claim_value)}</span><small>${sourceLink(x.source,x.source?.organization)} • verified ${esc(x.last_verified)}</small></div>`).join('')}`:''}<h3>Role profile</h3><div class="detail-grid">${Object.entries(d).filter(([k,v])=>v&&!['Market status','Salary context','O*NET role link','Wage source link','Evidence link'].includes(k)).map(([k,v])=>`<div class="detail"><h4>${esc(k)}</h4><p>${esc(v)}</p></div>`).join('')}</div><h3>How the ten college paths support this role</h3><div class="support-grid">${groups.map(([label,codes])=>{const ps=Object.entries(c.support).filter(([k,v])=>codes.includes(v)).map(([k])=>progByCode(k));return `<div class="support-box"><h4>${label}</h4>${ps.length?`<ul>${ps.map(p=>`<li><a href="#" onclick="event.preventDefault();openProgram('${p.code}')">${p.code} — ${esc(p.title)}</a></li>`).join('')}</ul>`:'<span class="subtle">None identified</span>'}</div>`}).join('')}</div><h3>Explore nearby possibilities</h3><p class="subtle">These controls intentionally broaden the search rather than treating the current role list as a closed universe.</p><div class="chipbar">${quick.map(x=>`<button class="chip" onclick="careerExcept('${esc(name).replace(/'/g,"\\'")}','${x}')">${x}</button>`).join('')}</div><div id="nearbyCareers"></div><div class="actions"><button class="btn ${state.savedCareers.includes(c.name)?'soft':''}" onclick="toggle(state.savedCareers,'${esc(c.name).replace(/'/g,"\\'")}');openCareer('${esc(c.name).replace(/'/g,"\\'")}')">★ ${state.savedCareers.includes(c.name)?'Saved':'Save career'}</button><button class="btn" onclick="state.progression.career='${esc(c.name).replace(/'/g,"\\'")}';save();closeModal();go('progression')">Career progression →</button>${d['O*NET role link']?`<a class="btn" target="_blank" href="${esc(d['O*NET role link'])}">O*NET ↗</a>`:''}</div></div></div></div>`}'''
s=s[:start]+open_career+s[end:]

# Add evidence page before glossary function
insert=s.index('function renderGlossary()')
evidence_page=r'''function renderEvidence(){const S=D.dataSummary,tier=x=>S.sourceTierCounts?.[x]||0;const sourceCards=(D.sources||[]).sort((a,b)=>a.authority_tier.localeCompare(b.authority_tier)||a.organization.localeCompare(b.organization));const groups={};for(const d of D.domains||[]){groups[d.domain_id]=D.roleFamilies.filter(f=>f.domain_id===d.domain_id)}app.innerHTML=`<div class="page"><div class="section-title"><div><div class="eyebrow">Research database • snapshot ${esc(S.asOf)}</div><h1>Market & Evidence</h1><p>The site now separates canonical career concepts from the titles employers actually use. This page shows what is in the research database, where it came from, and where coverage is still incomplete.</p></div></div><div class="stats-grid"><div class="stat"><b>${S.canonicalRoles}</b><span>canonical roles / pathways</span></div><div class="stat"><b>${S.roleFamilies}</b><span>role families</span></div><div class="stat"><b>${S.observedTitles}</b><span>observed market titles</span></div><div class="stat"><b>${S.currentRecentPostings}</b><span>current/recent postings</span></div><div class="stat"><b>${S.explicitProgressionEdges}</b><span>explicit progression edges</span></div><div class="stat"><b>${S.sources}</b><span>registered sources</span></div></div><div class="notice" style="margin-top:18px"><b>The map is deliberately open-ended.</b> A role can exist even when no current posting is in this snapshot, and employers may use titles not yet observed here. The database records both what is verified and what still needs more evidence rather than treating the displayed list as the boundary of possible careers.</div><div class="section-title"><div><h2>How the data is organized</h2></div></div><div class="grid cols-3"><div class="card"><h3>1. Canonical role</h3><p>A stable concept used for exploration, such as Wildlife Biologist or Behavioral Husbandry Specialist.</p></div><div class="card"><h3>2. Real market observations</h3><p>Employer titles, job postings, staff directories, salary ranges, credentials and qualification standards are linked back to the canonical role.</p></div><div class="card"><h3>3. Evidence-backed connections</h3><p>College preparation and career progression can be explained through competencies, formal requirements and explicit progression edges.</p></div></div><div class="section-title"><div><h2>Career taxonomy</h2><p>${S.domains} domains contain ${S.roleFamilies} role families. Role families keep a growing title universe navigable without pretending each employer title is a separate profession.</p></div></div>${(D.domains||[]).map(d=>`<div class="card taxonomy-domain"><h3>${esc(d.name)} <span>${d.roleCount} roles</span></h3><p>${esc(d.description)}</p><div class="chipbar">${(groups[d.domain_id]||[]).map(f=>`<span class="chip static">${esc(f.name)} · ${f.role_count}</span>`).join('')}</div></div>`).join('')}<div class="section-title"><div><h2>Source hierarchy</h2><p>Different source types answer different questions. Current job postings are strongest for titles, duties and salary observations; federal/professional standards are stronger for qualifications and credentials.</p></div></div><div class="grid cols-3"><div class="card"><div class="kicker">Tier A • ${tier('A')} sources</div><h3>Official / authoritative</h3><p>Federal qualification standards, permits, agency staff directories and other primary institutional sources.</p></div><div class="card"><div class="kicker">Tier B • ${tier('B')} sources</div><h3>Professional organizations</h3><p>Organizations such as AZA, The Wildlife Society, NWRA and professional credential bodies.</p></div><div class="card"><div class="kicker">Tier C • ${tier('C')} sources</div><h3>Observed employers / postings</h3><p>Individual job postings and employer evidence used to validate market titles, duties, experience and pay.</p></div></div><div class="section-title"><div><h2>Registered sources</h2></div></div><div class="source-table"><div class="source-row source-head"><b>Tier</b><b>Organization</b><b>Use</b><b>Retrieved</b></div>${sourceCards.map(x=>`<div class="source-row"><span class="tier tier-${esc(x.authority_tier)}">${esc(x.authority_tier)}</span><span><b>${esc(x.organization)}</b><small>${esc(x.title)}</small></span><span>${esc(x.source_type.replaceAll('_',' '))}</span><span>${esc(x.retrieved_date)}<br>${sourceLink(x,'source')}</span></div>`).join('')}</div><div class="section-title"><div><h2>Coverage still being expanded</h2></div></div><div class="card"><p><b>${S.rolesWithPostingEvidence}/${S.canonicalRoles}</b> roles have a current/recent posting in this snapshot and <b>${S.rolesWithObservedTitles}/${S.canonicalRoles}</b> have at least one directly observed title. That is intentional transparency, not an implication that the remaining roles are invalid.</p><p>Next research priorities include deeper posting evidence for shelter behavior, sanctuary work, comparative cognition, conservation breeding/population management, and additional salary and progression observations.</p><div class="actions"><button class="btn primary" onclick="go('careers')">Explore the career map</button></div></div></div>`} 

'''
s=s[:insert]+evidence_page+s[insert:]

APP.write_text(s,encoding='utf-8')

# nav
h=IDX.read_text(encoding='utf-8')
if 'data-route="evidence"' not in h:
    h=h.replace('<a href="#progression" data-route="progression">Progression</a>','<a href="#progression" data-route="progression">Progression</a>\n    <a href="#evidence" data-route="evidence">Market & Evidence</a>')
IDX.write_text(h,encoding='utf-8')

# styles
c=CSS.read_text(encoding='utf-8')
c += r'''
/* Evidence-backed career map */
.tag.evidence.market{background:#dcefe7;color:#155b48}.tag.evidence.verified{background:#e4edf7;color:#315a7d}.tag.evidence.established{background:#f2e9d9;color:#76551d}.observed-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.observed-title{border:1px solid var(--line);border-radius:11px;padding:11px;background:#fbfcfb;display:grid;gap:2px}.observed-title span,.observed-title small{color:var(--muted);font-size:12px}.posting-list{display:grid;gap:8px}.posting{display:flex;justify-content:space-between;gap:15px;border:1px solid var(--line);border-radius:11px;padding:11px;background:#fbfcfb}.posting>div:first-child{display:grid}.posting span{font-size:12px;color:var(--muted)}.posting-right{text-align:right;display:grid;align-content:start;gap:3px}.evidence-summary{margin-top:16px}.qualification{margin:8px 0}.qualification h4{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.evidence-claim{display:grid;grid-template-columns:145px 1fr;gap:6px 14px;padding:11px 0;border-bottom:1px solid var(--line)}.evidence-claim small{grid-column:2;color:var(--muted)}.chip.static{cursor:default}.source-mini{font-size:12px;margin:8px 0}.stats-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}.stat{background:white;border:1px solid var(--line);border-radius:14px;padding:16px}.stat b{display:block;font-size:26px;color:var(--accent)}.stat span{display:block;color:var(--muted);font-size:12px}.taxonomy-domain{margin-bottom:10px}.taxonomy-domain h3{display:flex;justify-content:space-between;gap:10px}.taxonomy-domain h3 span{font-size:12px;color:var(--muted);font-weight:600}.source-table{border:1px solid var(--line);border-radius:14px;overflow:hidden;background:white}.source-row{display:grid;grid-template-columns:60px 2fr 1fr 1fr;gap:12px;padding:11px 14px;border-bottom:1px solid var(--line);align-items:start}.source-row:last-child{border-bottom:0}.source-row span:nth-child(2){display:grid}.source-row small{color:var(--muted)}.source-head{background:#eef4f1}.tier{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:50%;font-weight:800}.tier-A{background:#dcefe7;color:#155b48}.tier-B{background:#e4edf7;color:#315a7d}.tier-C{background:#f2e9d9;color:#76551d}
@media(max-width:900px){.stats-grid{grid-template-columns:repeat(3,1fr)}.source-row{grid-template-columns:45px 1.7fr 1fr}.source-row>*:last-child{grid-column:2/4}.observed-grid{grid-template-columns:1fr}}
@media(max-width:620px){.stats-grid{grid-template-columns:repeat(2,1fr)}.source-row{grid-template-columns:40px 1fr}.source-row>*:nth-child(n+3){grid-column:2}.posting{display:grid}.posting-right{text-align:left}.evidence-claim{grid-template-columns:1fr}.evidence-claim small{grid-column:1}}
'''
CSS.write_text(c,encoding='utf-8')
print('patched evidence-aware site')
